WITH ranked_options AS ( SELECT p.product_id, p.product_type, p.kor_co_nm, p.fin_prdt_nm, p.join_way, p.max_limit, po.product_option_id, po.save_trm, po.intr_rate, po.intr_rate2, po.rsrv_type, po.rsrv_type_nm, ROW_NUMBER() OVER ( PARTITION BY p.product_id ORDER BY COALESCE(po.intr_rate2, -1) DESC, COALESCE(po.intr_rate, -1) DESC, po.product_option_id ASC ) AS option_rank FROM products p INNER JOIN product_options po ON p.product_id = po.product_id WHERE p.product_type = #{productType}
AND po.save_trm IN
#{savingTerm}
AND ( p.kor_co_nm LIKE CONCAT('%', #{keyword}, '%') OR p.fin_prdt_nm LIKE CONCAT('%', #{keyword}, '%') )
AND po.rsrv_type IN
#{reserveType}
AND EXISTS ( SELECT 1 FROM product_preferential_conditions ppc WHERE ppc.product_id = p.product_id AND ppc.condition_type = #{conditionType} )
)
SELECT product_id, product_type, kor_co_nm AS financial_company_name, fin_prdt_nm AS product_name, save_trm AS saving_term, intr_rate AS interest_rate, intr_rate2 AS maximum_interest_rate, max_limit, join_way, rsrv_type AS reserve_type, rsrv_type_nm AS reserve_type_name FROM ranked_options WHERE option_rank = 1
ORDER BY maximum_interest_rate IS NULL ASC, maximum_interest_rate ASC, product_id ASC
ORDER BY interest_rate IS NULL ASC, interest_rate DESC, product_id ASC
ORDER BY interest_rate IS NULL ASC, interest_rate ASC, product_id ASC
ORDER BY product_name ASC, product_id ASC
ORDER BY financial_company_name ASC, product_id ASC
ORDER BY maximum_interest_rate IS NULL ASC, maximum_interest_rate DESC, product_id ASC
LIMIT #{size} OFFSET #{offset}

WITH ranked_options AS ( SELECT p.product_id, ROW_NUMBER() OVER ( PARTITION BY p.product_id ORDER BY COALESCE(po.intr_rate2, -1) DESC, COALESCE(po.intr_rate, -1) DESC, po.product_option_id ASC ) AS option_rank FROM products p INNER JOIN product_options po ON p.product_id = po.product_id WHERE p.product_type = #{productType}
AND po.save_trm IN
#{savingTerm}
AND ( p.kor_co_nm LIKE CONCAT('%', #{keyword}, '%') OR p.fin_prdt_nm LIKE CONCAT('%', #{keyword}, '%') )
AND po.rsrv_type IN
#{reserveType}
AND EXISTS ( SELECT 1 FROM product_preferential_conditions ppc WHERE ppc.product_id = p.product_id AND ppc.condition_type = #{conditionType} )
)
SELECT COUNT(*) FROM ranked_options WHERE option_rank = 1
